import React from "react";
import {
  Container,
  List,
} from "@mui/material";
import MenuIcon from "@mui/icons-material/Menu";
import { ProductCard } from "../product-card";
import RookLevelImage from "../../assets/RookLevel.png"
import QuestionMarkImage from "../../assets/question-mark.png";
import BlackHoleImage from "../../assets/BlackHolesLogo.png";


type Status = "Ready" | "In progress" | "Planned";

interface IProduct {
    title: string;
    description: string;
    status: Status;
    image: string;
    link?: string;
}

export const ProductsSection: React.FC = () => {
  const products: IProduct[] = [
    {
      title: "Lizard slayer",
      description:
        "Thought provoking psychedelic first person shooter. The setting is mix of post-soviet country and ancient rus.",
      status: "Ready",
      image: RookLevelImage,
      link: "https://obscure-endeavor.itch.io/lizard-slayer"
    },
    {
      title: "Black Holes Diver",
      description:
        "Roguelike FPS with dymanic gameplay. Humanity is doomed, civilization has fallen and you are its last hope for salvation!",
        status: "In progress",
      image: BlackHoleImage,
      link: "https://obscure-endeavor.itch.io/black-holes-diver"
    }
  ];

  return (
    <Container maxWidth="lg" sx={{ py: 8 }}>
        <List sx={{ display: 'flex', flexDirection: "column", gap: 20 }}>
           {products.map((props) => (
                <ProductCard {...props} />
            ))}
        </List>
    </Container>
  );
};
   