import React, { useCallback } from "react";
import {
  AppBar,
  Toolbar,
  Typography,
  Button,
  Container,
  Box,
  Grid,
  Paper,
  IconButton,
  List,
} from "@mui/material";
import MenuIcon from "@mui/icons-material/Menu";

import "./product-card.css"

export interface IProductCardProps {
  title: string;
  description: string;
  image: string;
  link?: string;
}

export const ProductCard: React.FC<IProductCardProps> = ({ title, description, image, link }) => {
  const handleClick = useCallback(() => {
    link && window.open(link, "_target");
  }, [link]);

  return (
    <Paper
      elevation={3}
      sx={{
        p: 3,
        height: "100%",
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        backgroundImage: `url(${image})`,
      }}
      className="product-card"
    >
      <div className="product-card-list">
          {description && (
            <Typography
              variant="body2"
              sx={{ color: "common.white", opacity: 0.85, mt: 0.5 }}
              className="product-card-description"
            >
              {description}
            </Typography>
          )}
          <div>
            <div onClick={handleClick}>
              <Typography variant="h6" fontWeight="bold" gutterBottom className="product-card-title" >
                {title}
              </Typography>
            </div>
          </div>

      </div>
    </Paper>
  );
};