import React from "react";
import { StyledLink } from "../styled-link";
import "./links.css";

interface ILinkItem {
    description: string;
    value: string;
}

const items: ILinkItem[] = [
    { description: "Itch", value: "https://obscure-endeavor.itch.io/" },
    { description: "Telegram", value: "https://t.me/OBSCURE_ENDEAVOR" },
    { description: "YouTube", value: "https://www.youtube.com/channel/UCZ0iagLHdtEMVzPddM08WNQ" },
];

export const Links = () => {
    return <div className="links-container">
        {items.map(x => {
            return <StyledLink href={x.value} ><h3>{x.description}</h3></StyledLink>
        })}
    </div>
}
