import React, { useCallback } from "react";
import {
  AppBar,
  Typography,
  Button,
  Container,
  Box,
  IconButton,
} from "@mui/material";
import MenuIcon from '@mui/icons-material/Menu';
import LogoImage from "../../assets/CompanyLogo.jpg";
import { useNavigate } from "react-router-dom";

interface INavItem {
  name: string;
  link: string;
}
const navItems: INavItem[] = [{ name: "Games", link: "/"} , { name: "Follow us", link: "/follow"}];

export const Header: React.FC = () => {

  const navigate = useNavigate();

  const handleLinkClick = useCallback((item: INavItem) => {
    navigate(item.link);
  }, []);

  return (
    <AppBar position="static" color="transparent" elevation={0} sx={{ py: 2 }}>
      <Container maxWidth="lg" sx={{ display: "flex", alignItems: "center", bgcolor: "background.default", color: "text.primary" }}>
        <Typography variant="h6" sx={{ flexGrow: 1, fontWeight: "bold" }}>
          <img src={LogoImage} width={300} height={60}/>
        </Typography>
        <Box sx={{ display: { xs: "none", md: "flex" }, gap: 3 }}>
          {navItems.map((item) => (
            <Button key={item.name} color="inherit" sx={{ fontWeight: "bold" }} onClick={() => handleLinkClick(item)}>
              {item.name}
            </Button>
          ))}
        </Box>
      </Container>
    </AppBar>
  );
}
