import React, { useEffect, useMemo, useState } from "react";
import { Box, Typography, IconButton, Paper, useTheme } from "@mui/material";
import ChevronLeftIcon from "@mui/icons-material/ChevronLeft";
import ChevronRightIcon from "@mui/icons-material/ChevronRight";
import { INewsItemProps, NewsItem } from "../news-item/news-item";

import "./news-carousel.css";

export interface INewsItem {
  title: string;
  description: string;
  imageUrl?: string;
  image?: string;
}

interface NewsCarouselProps {
  items: INewsItemProps[];
}

export const NewsCarousel: React.FC<NewsCarouselProps> = ({ items }) => {
  const [index, setIndex] = useState(0);
  const theme = useTheme();

  const prev = () => setIndex((i) => (i === 0 ? items.length - 1 : i - 1));
  const next = () => setIndex((i) => (i === items.length - 1 ? 0 : i + 1));

  const current = useMemo(() => items[index], [index]);

  return (
    <div className="news-carousel-container">
      <div
        className="news-carousel-container-2" 
      >
        <IconButton aria-label="previous" onClick={prev}>
          <ChevronLeftIcon fontSize="large" />
        </IconButton>
        <NewsItem {...current}/>
        <IconButton aria-label="next" onClick={next}>
          <ChevronRightIcon fontSize="large" />
        </IconButton>
      </div>
      <Box sx={{ textAlign: "center", mt: 2 }}>
        {items.map((_, i) => (
          <Box
            key={i}
            component="span"
            sx={{
              display: "inline-block",
              width: 10,
              height: 10,
              bgcolor: i === index ? theme.palette.primary.main : theme.palette.action.disabled,
              borderRadius: "50%",
              mx: 0.5,
              transition: "background 0.2s",
            }}
          />
        ))}
      </Box>
    </div>
  );
};
