import React, { useMemo } from "react";
import {
  AppBar,
  Toolbar,
  Typography,
  Button,
  Container,
  Box,
  Grid,
  Paper,
  IconButton,
} from "@mui/material";
import MenuIcon from "@mui/icons-material/Menu";
import parse from 'html-react-parser';

export interface INewsItemProps {
  title: string;
  description: string;
  videoUrl?: string;
  imageUrl?: string;
}

export const NewsItem: React.FC<INewsItemProps> = ({ title, description, videoUrl, imageUrl }) => {

  const descriptionHtml = useMemo(() => {
    return parse(description);
  }, [description]);

  return (
    <Box
      sx={{
        bgcolor: "#222",
        textAlign: "center",
        py: 10,
        px: 3,
        color: "text.primary",
        width: "100%"
      }}
    >
      <Typography variant="h3" fontWeight="bold" gutterBottom>
        {title}
      </Typography>
      <Typography variant="h6" sx={{ maxWidth: 600, mx: "auto", mb: 4 }}>
        {descriptionHtml}
      </Typography>
      {videoUrl && <video autoPlay={true} loop={true} playsInline={true} muted={true} width="60%" >
        <source src={videoUrl} type="video/mp4" />
      </video>}
      {imageUrl && <img src={imageUrl} width="60%"/>}
    </Box>
  );
};
