import React, { useMemo } from "react";
import {
  AppBar,
  Toolbar,
  Typography,
  Button,
  Container,
  Box,
} from "@mui/material";

export const Footer: React.FC = () => {
  const currentYear = useMemo( ()=> new Date().getFullYear(), []);
  
  return (
    <Box
      component="footer"
      sx={{
        bgcolor: "#222",
        color: "#fff",
        py: 4,
        textAlign: "center",
        mt: 6,
      }}
    >
      <Typography variant="body2">
        &copy; {currentYear} Obscure Endeavor. All rights reserved.
      </Typography>
    </Box>
  );
};